onClick:
{{
(async () => {
  await storeValue(
    "adminInvitarResultado",
    "",
    false
  );

  const correo = (
    inpAdminInvitarCorreo.text || ""
  ).trim().toLowerCase();

  const nombre = (
    inpAdminInvitarNombre.text || ""
  ).trim();

  const apellido = (
    inpAdminInvitarApellido.text || ""
  ).trim();

  const empresa =
    selAdminInvitarEmpresa.selectedOptionValue;

  const rol =
    selAdminInvitarRol.selectedOptionValue;

  if (!correo) {
    await storeValue(
      "adminInvitarResultado",
      "Ingresa el correo electrónico.",
      false
    );

    showAlert(
      "Ingresa el correo electrónico.",
      "warning"
    );

    return;
  }

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo)) {
    await storeValue(
      "adminInvitarResultado",
      "Ingresa un correo electrónico válido.",
      false
    );

    showAlert(
      "Ingresa un correo electrónico válido.",
      "warning"
    );

    return;
  }

  if (!nombre || !apellido) {
    await storeValue(
      "adminInvitarResultado",
      "Ingresa el nombre y apellido del usuario.",
      false
    );

    showAlert(
      "Ingresa el nombre y apellido del usuario.",
      "warning"
    );

    return;
  }

  if (!empresa) {
    await storeValue(
      "adminInvitarResultado",
      "Selecciona la empresa.",
      false
    );

    showAlert(
      "Selecciona la empresa.",
      "warning"
    );

    return;
  }

  if (!rol) {
    await storeValue(
      "adminInvitarResultado",
      "Selecciona el rol del usuario.",
      false
    );

    showAlert(
      "Selecciona el rol del usuario.",
      "warning"
    );

    return;
  }

  try {
    await qInviteErpUser.run();

    await storeValue(
      "adminInvitarResultado",
      "Invitación enviada correctamente.",
      false
    );

    showAlert(
      "Invitación enviada correctamente.",
      "success"
    );
  } catch (error) {
    const detalle = String(
      error?.message ||
      error?.responseMeta?.error?.message ||
      error?.response?.message ||
      JSON.stringify(error) ||
      "Error desconocido"
    );

    await storeValue(
      "adminInvitarResultado",
      "Error técnico: " + detalle.substring(0, 300),
      false
    );

    console.log(
      "Error qInviteErpUser:",
      error
    );
  }
})()
}}
